"任何房间": "Mana-mana bilik",
"任何房间：主基地耐久 +{0}%。契合「防御」：守城时 {1} 名陶土守卫加入战斗。": "Mana-mana bilik: ketahanan Kubu +{0}%. Serasi “Pertahanan”: {1} pengawal tanah liat turut bertahan.",
"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Mana-mana bilik: bawa {0} pusaka lagi dalam ekspedisi. Serasi “Pertahanan”: senjata memberi kerosakan +{1}%, memercik dan melambatkan apabila kena; yang lain dapat {2} pengawal tambahan.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Mana-mana bilik: bekalan dibawa pulang +{0}%. Serasi “Tuah”: bekalan +{1}% lagi, pengganda mata awal +{2} setiap pertempuran.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Mana-mana bilik: jarak pandang ekspedisi +{0}, pengganda mata awal +{1}. Serasi “Tuah / Khas”: peta ekspedisi terbuka sepenuhnya dari awal, pengganda +{2} lagi.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Mana-mana bilik: serangan pasukan ekspedisi +{0}%. Serasi “Latihan”: EXP ekspedisi Pemimpin +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Mana-mana bilik: HP pasukan ekspedisi +{0}%. Serasi “Perubatan”: pemulihan hospital +{1}%, pemimpin pulih {2}% lagi sehari.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Mana-mana bilik: kadar jatuhan pelan +{0}%. Serasi “Sains Fiksyen”: pangkalan +{1} Serpihan Jiwa sehari.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Mana-mana bilik: kadar jatuhan pelan +{0}%. Serasi “Penempaan”: {1}% peluang dapat pusaka tambahan semasa menempa.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Mana-mana bilik: pangkalan +{0} Serpihan Jiwa sehari. Serasi “Sihir”: +{1} lagi sehari.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Mana-mana bilik: pangkalan +{0} bekalan sehari. Serasi “Logistik”: kesan bilik ini sendiri ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Mana-mana bilik: pangkalan +{0} bekalan sehari, pemimpin dapat {1} EXP sehari. Serasi “Logistik / Alam”: kesan bilik ini sendiri ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Mana-mana bilik: kos tempaan pusaka -{0}%. Serasi “Penempaan / Senjata”: penempaan ada {1}% peluang kualiti +{2}; senjata memberi kerosakan +{3}%.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Mana-mana bilik: masa binaan separuh, {0}% bekalan dipulangkan apabila siap. Serasi “Keajaiban”: pulangan naik ke {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Mana-mana bilik: semua menara pertahanan memberi kerosakan +{0}%. Serasi “Senjata”: jarak +{1}, kelajuan serangan +{2}%.",
"任何房间：挖掘费用 -{0}%。契合「特殊」：所有建造少花 {1} 天。": "Mana-mana bilik: kos galian -{0}%. Serasi “Khas”: semua binaan {1} hari lebih cepat.",
"任何房间：每场战斗初始积分倍率 +{0}。契合「锻造」：打造的宝物品质必定 +{1}。": "Mana-mana bilik: pengganda mata awal +{0} setiap pertempuran. Serasi “Penempaan”: pusaka tempaan pasti kualiti +{1}.",
"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Mana-mana bilik: masa bertenang skil pemimpin {0} hentian lebih singkat. Serasi “Tuah”: mulakan ekspedisi dengan {1} item sokongan tambahan (sekurang-kurangnya kesan “Epik”).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Mana-mana bilik: serangan Pemimpin +{0}%. Serasi “Senjata”: kerosakan +{1}%, setiap serangan melepaskan kilat berantai (melompat ke {2} musuh).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Mana-mana bilik: pemimpin pulih {0}% HP sehari (tanpa hospital). Serasi “Perubatan / Perairan”: pemulihan hospital +{1}%; jarak senjata air +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Mana-mana bilik: pemimpin dapat {0} EXP sehari. Serasi “Pengeluaran”: hasil bilik ini sendiri ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Mana-mana bilik: pemimpin dapat {0} EXP sehari. Serasi “Latihan”: EXP ekspedisi Pemimpin +{1}%.",
"任何房间：领袖生命 +{0}%。契合「训练」：领袖攻击 +{1}%。": "Mana-mana bilik: HP Pemimpin +{0}%. Serasi “Latihan”: serangan Pemimpin +{1}%.",
