"前面是": "Di hadapan ialah",
"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Di hadapan ialah “Tanah Perkuburan”: kabus paling tebal di sana, dan kubur baharu bertambah setiap malam.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Di hadapan ialah “Dewan Pemasangan”: benda terakhir yang dibuat kilang itu memasukkan semua orang kilang ke dalamnya.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Di hadapan ialah “Bilik Bedah”: tuan pengarah kata pembedahan berjaya—pesakit cuma belum sedar.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Di hadapan ialah “Dasar Laut”: di bawah pelabuhan ada sebuah kota lagi, dan pintu kotanya ialah sebuah mulut.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Di hadapan ialah “Pohon Ilmu”: ia mengingati segala yang pernah berlaku di hutan, dan tidak mahu mengingati apa-apa lagi.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Di hadapan ialah “Ratu Bunian”: baginda menunggu di tepi kolam bulan selama tiga ratus tahun. Katanya, andalah orang yang ditunggunya.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "Di hadapan ialah “Khemah Sarkas”: gelak ketawa di dalamnya tidak pernah berhenti—cuma tiada lagi penonton.",
